class Solution:
    def countSquares(self, matrix: list[list[int]]) -> int:
        m, n = len(matrix), len(matrix[0])
        dp = [[0] * n for _ in range(m)]
        ans = 0
        for r in range(m):
            for c in range(n):
                if matrix[r][c]:
                    dp[r][c] = 1 if r == 0 or c == 0 else 1 + min(dp[r - 1][c], dp[r][c - 1], dp[r - 1][c - 1])
                    ans += dp[r][c]
        return ans

