class Solution:
    def countSquares(self, matrix: list[list[int]]) -> int:
        m, n = len(matrix), len(matrix[0])
        dp = [0] * (n + 1)
        ans = 0
        for r in range(1, m + 1):
            diag = 0
            for c in range(1, n + 1):
                old = dp[c]
                if matrix[r - 1][c - 1]:
                    dp[c] = 1 + min(dp[c], dp[c - 1], diag)
                    ans += dp[c]
                else:
                    dp[c] = 0
                diag = old
        return ans

